function getTransition(fromId, toId, category, transitionVariant = "random") {
  const key = `${fromId}-${toId}`;
  const data = BIANUA_TRANSITIONS_V2[key];
  if (!data) return null;
  const variant = transitionVariant === "random" ? Math.random() < 0.5 ? "A" : "B" : transitionVariant;
  return {
    ...data,
    transitionText: data.transition[variant] || data.transition.A,
    categorySignal: data.signal[category] || data.signal.fate || data.signal.family || data.signal.career
  };
}
function buildTransitionContext(benGuaId, bianGuaId, category) {
  if (!bianGuaId) return "\u6B64\u5366\u65E0\u53D8\u5366\uFF0C\u5C40\u9762\u76F8\u5BF9\u7A33\u5B9A\uFF0C\u53C2\u8003\u672C\u5366\u5366\u6027\u5373\u53EF\u3002";
  const data = getTransition(benGuaId, bianGuaId, category);
  if (!data) {
    return `\u672C\u5366\u53D8\u4E3A${bianGuaId}\u5366\uFF0C\u5177\u4F53\u8F6C\u5316\u9700\u7ED3\u5408\u5366\u6027\u5224\u65AD\u3002`;
  }
  const natureMap = {
    improvement: "\u5411\u597D\u8F6C\u5316",
    deterioration: "\u8F6C\u5DEE\uFF0C\u9700\u8B66\u793A",
    transformation: "\u8D28\u7684\u8F6C\u53D8",
    stabilization: "\u8D8B\u4E8E\u7A33\u5B9A",
    warning: "\u6709\u9690\u60A3\uFF0C\u9700\u8FA8\u522B"
  };
  return `\u53D8\u5366\u8F6C\u5316\uFF1A\u3010${data.fromName}\u3011\u2192\u3010${data.toName}\u3011
\u8F6C\u5316\u6027\u8D28\uFF1A${natureMap[data.nature] || "\u8F6C\u5316\u4E2D"}
\u8F6C\u5316\u8C61\u610F\uFF1A${data.transitionText}
${category}\u8D70\u5411\u4FE1\u53F7\uFF1A${data.categorySignal}
\u65AD\u8BED\u65B9\u5411\uFF1A${data.verdict}
\u5199\u6CD5\u63D0\u793A\uFF1A${data.aiHint}`;
}
function getNatureLabel(nature) {
  const map = {
    improvement: "\u5411\u597D\u8F6C\u5316",
    deterioration: "\u8F6C\u5DEE\u8B66\u793A",
    transformation: "\u8D28\u7684\u8F6C\u53D8",
    stabilization: "\u8D8B\u4E8E\u7A33\u5B9A",
    warning: "\u6709\u9690\u60A3\u9700\u6CE8\u610F"
  };
  return map[nature] || "\u8F6C\u5316\u4E2D";
}

