function getEssence(guaId) {
  return HEXAGRAM_ESSENCE[guaId] || null;
}
function getSignal(guaId, category) {
  const entry = HEXAGRAM_ESSENCE[guaId];
  if (!entry) return null;
  return entry.signal[category] || null;
}
function buildEssenceContext(benGuaId, bianGuaId, category) {
  const ben = HEXAGRAM_ESSENCE[benGuaId];
  const bian = bianGuaId ? HEXAGRAM_ESSENCE[bianGuaId] : null;
  if (!ben) return "";
  let ctx = `\u672C\u5366\u3010${ben.name}\u3011\u5366\u6027\uFF1A${ben.essence}`;
  if (ben.signal[category]) {
    ctx += `
${category}\u65B9\u5411\u4FE1\u53F7\uFF1A${ben.signal[category]}`;
  }
  if (bian) {
    ctx += `
\u53D8\u5366\u3010${bian.name}\u3011\u5366\u6027\uFF1A${bian.essence}`;
    if (bian.signal[category]) {
      ctx += `
\u53D8\u5366${category}\u4FE1\u53F7\uFF1A${bian.signal[category]}`;
    }
  }
  return ctx;
}

// src/lib/interpret-format.ts
var COLON_LABEL = /^([^：\n]{2,12})：([\s\S]*)$/;
var BRACKET_LABEL = /^【([^】]+)】([\s\S]*)$/;
function paragraphToLine(paragraph) {
  const trimmed = paragraph.trim();
  if (!trimmed) return { text: "" };
  const bracket = trimmed.match(BRACKET_LABEL);
  if (bracket) {
    const label = bracket[1] === "\u4E0B\u4E00\u6B65" ? "\u957F\u671F\u6765\u770B" : bracket[1];
    return { label, text: bracket[2].trim() || trimmed };
  }
  const colon = trimmed.match(COLON_LABEL);
  if (colon && !/[，。]/.test(colon[1])) {
    return { label: colon[1], text: colon[2].trim() };
  }
  if (trimmed.startsWith("\u6885\u82B1\u7B56\u7565")) {
    return { label: "\u7B56\u7565", text: trimmed };
  }
  return { text: trimmed };
}
function paragraphsToLines(paragraphs) {
  return paragraphs.map((p) => p.trim()).filter(Boolean).map(paragraphToLine).filter((l) => l.text);
}
function textToLines(text) {
  return paragraphsToLines(text.split(/\n\n+/));
}
function linesToAnalysis(lines) {
  return lines.filter((l) => l.text.trim()).map((l) => l.label ? `${l.label}\uFF1A${l.text}` : l.text).join("\n\n");
}

