      { tone: "empathy", text: "\u4F60\u4E00\u76F4\u5728\u52AA\u529B\uFF0C\u4F46\u8FD9\u4E00\u5366\u8BF4\uFF0C\u6709\u65F6\u5019\u987A\u6D41\u800C\u4E0B\u6BD4\u9006\u6D41\u66F4\u5BF9\u3002" },
      { tone: "warning", text: "\u8C6B\u5366\u5EFA\u4FAF\u884C\u5E08\uFF0C\u987A\u52BF\u7684\u524D\u63D0\u662F\u65B9\u5411\u5BF9\uFF0C\u65B9\u5411\u4E0D\u5BF9\u987A\u52BF\u4E5F\u662F\u9519\u3002" },
      { tone: "encourage", text: "\u8C6B\uFF0C\u5229\u5EFA\u4FAF\u884C\u5E08\uFF0C\u8DDF\u5BF9\u4E86\u4EBA\u6216\u52BF\uFF0C\u8FD9\u4EF6\u4E8B\u4F1A\u987A\u5229\u3002" }
