      { tone: "empathy", text: "\u4F60\u73B0\u5728\u9762\u5BF9\u7684\u95EE\u9898\u4E0D\u662F\u65B0\u95EE\u9898\uFF0C\u662F\u79EF\u7D2F\u5DF2\u4E45\u7684\uFF0C\u6B63\u89C6\u5B83\u3002" },
      { tone: "warning", text: "\u86CA\u5143\u4EA8\uFF0C\u5148\u7532\u4E09\u65E5\u540E\u7532\u4E09\u65E5\uFF0C\u6574\u6CBB\u9700\u8981\u65F6\u95F4\uFF0C\u4E0D\u662F\u4E00\u8E74\u800C\u5C31\u7684\u3002" },
      { tone: "encourage", text: "\u86CA\u5366\u6574\u6CBB\u4E4B\u540E\uFF0C\u5143\u4EA8\uFF0C\u6E05\u7406\u4E4B\u540E\u5C40\u9762\u4F1A\u597D\u8D77\u6765\u7684\u3002" }
