      { tone: "poetic", text: "\u660E\u51FA\u5730\u4E0A\uFF0C\u664B\uFF0C\u5982\u65E5\u521D\u5347\uFF0C\u4E0A\u5347\u52BF\u5934\u660E\u786E\uFF0C\u987A\u52BF\u800C\u4E0A\u3002" },
      { tone: "empathy", text: "\u4F60\u7B49\u7684\u90A3\u4E2A\u673A\u4F1A\uFF0C\u8FD9\u4E00\u5366\u8BF4\uFF0C\u6765\u4E86\u3002" },
      { tone: "warning", text: "\u664B\u5982\uFF0C\u6467\u5982\uFF0C\u8D1E\u5409\uFF0C\u4E0A\u5347\u7684\u8DEF\u8981\u8D70\u5F97\u7A33\uFF0C\u6025\u8FDB\u53CD\u800C\u4F1A\u632B\u6298\u3002" },
      { tone: "encourage", text: "\u5EB7\u4FAF\u7528\u9521\u9A6C\u8543\u5EB6\uFF0C\u664B\u5366\u7684\u56DE\u62A5\u662F\u4E30\u539A\u7684\uFF0C\u65B9\u5411\u662F\u5BF9\u7684\u3002" }
